'use client'

// The gate-handshake explainer on /gates (gate-fixtures run, 2026-10-10): one animated SVG,
// generated by scripts/build-gate-handshake.mjs from the reference repo's illustrative contrast
// record (two fixture presenters, one gate), inlined so it takes the page's own fonts. CSS keyframes
// only, no audio. With reduced motion the SVG holds the report beat and the steps below are open.
import { memo, useEffect, useRef, useState } from 'react'
import { Pause, Play, RotateCcw } from 'lucide-react'
import { GATE_HANDSHAKE_SVG, GATE_HANDSHAKE_TRANSCRIPT } from '@/data/gateHandshake'

// The inlined SVG lives in a memoized child so a state change (pause, reduced motion) never
// re-renders it: React re-applying the markup would replace the node and restart the timeline.
const Art = memo(function Art() {
  return (
    <div
      className="-mx-3 sm:mx-0 [&_svg]:block [&_svg]:h-auto [&_svg]:w-full"
      dangerouslySetInnerHTML={{ __html: GATE_HANDSHAKE_SVG }}
    />
  )
})

export function GateHandshake() {
  const frame = useRef<HTMLDivElement>(null)
  const [paused, setPaused] = useState(false)
  const [reducedMotion, setReducedMotion] = useState(false)

  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)')
    const update = () => setReducedMotion(query.matches)
    update()
    query.addEventListener('change', update)
    return () => query.removeEventListener('change', update)
  }, [])

  const restart = () => {
    const svg = frame.current?.querySelector('svg')
    svg?.getAnimations({ subtree: true }).forEach((a) => {
      a.currentTime = 0
    })
    setPaused(false)
  }

  return (
    <figure className="mx-auto max-w-3xl">
      <div ref={frame} className={paused ? 'gh-paused' : undefined}>
        <Art />
      </div>
      <figcaption className="mt-3 flex flex-wrap items-center justify-between gap-3">
        <span className="text-xs leading-5 text-text-muted">
          Illustrative: the counterparty-onboarding example, run by the reference gate on its two
          fixture presenters. Every value is from that run’s record.
        </span>
        {!reducedMotion && (
          <span className="flex gap-2">
            <button
              type="button"
              onClick={() => setPaused((p) => !p)}
              className="inline-flex items-center gap-1.5 rounded-full border border-white/15 px-3 py-1.5 text-xs font-semibold text-text-primary transition-colors hover:border-white/35 hover:bg-white/5"
              aria-pressed={paused}
            >
              {paused ? <Play size={13} /> : <Pause size={13} />}
              {paused ? 'Play' : 'Pause'}
            </button>
            <button
              type="button"
              onClick={restart}
              className="inline-flex items-center gap-1.5 rounded-full border border-white/15 px-3 py-1.5 text-xs font-semibold text-text-primary transition-colors hover:border-white/35 hover:bg-white/5"
            >
              <RotateCcw size={13} />
              Restart
            </button>
          </span>
        )}
      </figcaption>
      <details className="mt-4 text-sm text-text-secondary" open={reducedMotion}>
        <summary className="cursor-pointer text-xs font-semibold text-text-muted transition-colors hover:text-text-primary">
          The handshake, step by step
        </summary>
        <ol className="mt-3 list-decimal space-y-2 pl-5 leading-6">
          {GATE_HANDSHAKE_TRANSCRIPT.map((step) => (
            <li key={step} className="break-words">
              {step}
            </li>
          ))}
        </ol>
      </details>
    </figure>
  )
}
